    }
  }

  for (const [route, actions] of planned) {
    if (actions.length > 1) {
      diagnostics.push({
        code: "planner.route.duplicate",
        severity: "error",
        category: "ai",
        message: `Multiple planned pages use route: ${route}.`,
      });
    }
  }

  return diagnostics;
}
